import unittest,re
from tools.kjv_archive import load_register,read
class EphesiansBodyAccessTests(unittest.TestCase):
 def test_two_groups_one_body(self):
  prior,_=load_register('0.10-kjv.248');lang,manifest=load_register('0.10-kjv.249')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('ephesians-'):c for c in read(lang.folder/'ephesians-two-groups-one-body-cases.json')};self.assertEqual(len(cases),66)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'1:1': ['kjv_paul_acts', 'at kjv_ephesus_acts', 'faithful:pl in kjv_christ_title'], '1:2': ['god ourone/father', 'kjv_lord kjv_jesus_matthew kjv_christ_title'], '1:3': ['god and father of ourone/kjv_lord', 'wesg:a with all spirit:adj blessing:pl', 'heavenly place:pl'], '1:4': ['before world kjv_foundation', 'holy and without blame', 'in love'], '1:5': ['child:pl adoption', 'to himself kjv_predestinate_romans:perf', 'his/will'], '1:6': ['his/grace glory', 'in beloved', 'accept:psv:adj make:perf'], '1:7': ['redeem:ev through his/blood', 'forgive:ev of sin:pl', 'his/grace wealth'], '1:8': ['towards wesg', 'all wisdom and kjv_prudence'], '1:9': ['mystery of his/will', 'he in himself purpose:perf'], '1:10': ['kjv_dispensation_order_ephesians', 'time:pl full:ev', 'in one_num gather:may', 'which in heaven and which on earth'], '1:11': ['inheritance obtain:perf', 'all thing:pl', 'counsel of his/own will'], '1:12': ['wesg who first', 'his/glory praise'], '1:13': ['after you truth word', 'after you believe:pa', 'holy spirit of promise seal:psv:pa'], '1:14': ['ourone/inheritance kjv_earnest_pledge_corinthians', 'buy:psv:adj kjv_possession redeem:ev'], '1:15': ['i also after i', 'your/faith in kjv_lord', 'all saint:pl'], '1:16': ['thanks give:inf cease:neg:pr', 'my/pray:ev:pl', 'kjv_mention:cv'], '1:17': ['god of ourone/kjv_lord', 'glory father', 'wisdom and reveal:ev spirit'], '1:18': ['your/understand:ev eye:pl', 'his/call:ev hope', 'his/inheritance glory wealth'], '1:19': ['towards wesg who believe:pr', 'his/mighty power work:ev'], '1:20': ['from dead:adj:pl raise:pa', 'his/own kjv_right_side hand'], '1:21': ['kjv_principality_ephesians and power and might and kjv_dominion', 'not only in this world'], '1:22': ['under his/foot:pl', 'head to kjv_church_assembly'], '1:23': ['his/body full:ev', 'all in all fill:pr'], '2:1': ['transgress:ev:pl and sin:pl', 'he quicken:perf'], '2:2': ['this world course', 'prince of air power', 'disobedience child:pl'], '2:3': ['wesg all', 'kjv_conversation_conduct_corinthians', 'flesh and mind', 'by nature wrath child:pl'], '2:4': ['god who in mercy rich', 'he wesg:a love:pa'], '2:5': ['wesg:a together with kjv_christ_title', 'by grace you save:psv:pr'], '2:6': ['wesg:a up together raise:perf', 'heavenly place:pl', 'together sit:caus:perf'], '2:7': ['age:pl to come:inf', 'his/grace exceed:cv wealth', 'his/kjv_kindness'], '2:8': ['by grace you through faith', 'not of yourselves', 'god gift'], '2:9': ['not of work:pl', 'lest any man boast:should'], '2:10': ['his/kjv_workmanship_ephesians', 'good work:pl', 'before kjv_ordain:perf', 'wesg in they walk:should'], '2:11': ['kjv_circumcise:neg:ev call:psv:pr', 'by hand:pl make:psv:adj kjv_circumcise:ev'], '2:12': ['without kjv_christ_title', 'kjv_commonwealth_ephesians', 'promise kjv_covenant:pl', 'no hope', 'without god'], '2:13': ['former:adv far away', 'by blood of kjv_christ_title near'], '2:14': ['ourone/peace', 'two group:pl one_num', 'middle wall of partition', 'between wesg'], '2:15': ['his/flesh enmity', 'law of command:pl in kjv_ordinance:pl', 'from two one_num new man'], '2:16': ['two group:pl to god in one_num body', 'kjv_cross_instrument', 'enmity thereby slay:perf'], '2:17': ['peace to you who far away', 'to they who near'], '2:18': ['wesg of two group:pl', 'by one_num spirit to father', 'kjv_access_romans'], '2:19': ['no more stranger:pl', 'fellow citizen:pl', 'of god kjv_household'], '2:20': ['kjv_apostle:pl and prophet:pl kjv_foundation', 'himself chief kjv_cornerstone_ephesians'], '2:21': ['all kjv_building_corinthians', 'together join:psv:adj', 'holy kjv_temple'], '2:22': ['you also together', 'god dwelling through spirit'], '3:1': ['i kjv_paul_acts kjv_prisoner', 'for you kjv_gentile:pl'], '3:2': ['god grace kjv_dispensation_order_ephesians', 'to i for you give:psv:pr'], '3:3': ['by reveal:ev', 'mystery to i', 'before in few word:pl'], '3:4': ['when you read:pr', 'my/know:ev', 'understand:pr:may'], '3:5': ['other age:pl', 'as now', 'his/holy kjv_apostle:pl and prophet:pl'], '3:6': ['kjv_fellowheir_ephesians:pl', 'of same body', 'his/promise in kjv_christ_title by kjv_gospel'], '3:7': ['i servant make:psv:pa', 'kjv_effectual_ephesians work:ev of his/power'], '3:8': ['less than least of all saint:pl', 'kjv_unsearchable_ephesians wealth'], '3:9': ['kjv_fellowship_mystery_ephesians', 'from world beginning', 'all thing:pl by kjv_jesus_matthew kjv_christ_title create:pa'], '3:10': ['kjv_principality_ephesians:pl and power:pl', 'by kjv_church_assembly', 'many form:adj wisdom'], '3:11': ['eternal purpose', 'ourone/kjv_lord'], '3:12': ['wesg bold:ev', 'confidence by faith of he'], '3:13': ['i desire:pr', 'my/kjv_tribulation:pl for you', 'your/glory'], '3:14': ['i my/knee:pl', 'father of ourone/kjv_lord kjv_jesus_matthew kjv_christ_title'], '3:15': ['whole kjv_family in heaven and earth'], '3:16': ['his/glory wealth', 'kjv_inner man by his/spirit', 'strengthen:psv:inf'], '3:17': ['your/heart:pl by faith dwell:may', 'in love root:psv:adj and ground:psv:adj'], '3:18': ['with all saint:pl', 'breadth and length and deep:ev and height'], '3:19': ['love of kjv_christ_title', 'know:ev exceed:pr', 'all full:ev of god'], '3:20': ['wesg ask:pr or think:pr', 'exceed:adv abundance:adv', 'power which in wesg work:pr'], '3:21': ['glory in kjv_church_assembly', 'through all age:pl', 'world without end', 'amen']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('wesg of two group:pl by one_num spirit to father',cases['2-18']['analysis'])
  self.assertNotIn('we:du',cases['2-18']['analysis'])
  self.assertIn('from two one_num new man',cases['2-15']['analysis'])
  self.assertIn('enmity thereby slay:perf',cases['2-16']['analysis'])
  self.assertIn('your/understand:ev eye:pl',cases['1-18']['analysis'])
  self.assertIn('kjv_fellowship_mystery_ephesians',cases['3-9']['analysis'])
  self.assertIn('by kjv_jesus_matthew kjv_christ_title create:pa',cases['3-9']['analysis'])
  self.assertIn('faith of he',cases['3-12']['analysis'])
  self.assertIn('father of ourone/kjv_lord kjv_jesus_matthew kjv_christ_title',cases['3-14']['analysis'])
  self.assertIn('whole kjv_family',cases['3-15']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),9)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
